{
  "query": "query($filtro: ConsultaFiltroInput) { historicoConsultas(filtro: $filtro) { id pacienteId profissionalId dataSolicitacao dataConsulta tipo status observacoes createdAt updatedAt } }",
  "variables": {
    "filtro": {
      "pacienteId": "{{paciente_id}}",
      "profissionalId": "{{profissional_id}}",
      "status": "CONFIRMADA"
    }
  }
}

