  "variables": {
    "id": "{{consulta_id}}"
  }
}

{
  "query": "{ historicoConsultas { id pacienteId profissionalId dataSolicitacao dataConsulta tipo status observacoes createdAt updatedAt } }",
  "variables": {}
}

